import requests

BASE_URL = "https://api.socbench.example"

# Start a monitoring process for the specified production line and configuration.
start_response = requests.post(
    f"{BASE_URL}/process/start",
    json={
        "productionLineId": "chemical-production-line-001",
        "parameters": {
            "temperature": 85,
            "pressure": 12,
            "materialTypes": ["plastic", "metal", "glass"],
        },
    },
)
start_response.raise_for_status()
process_id = start_response.json()["processId"]

# Archive logs from the initiated monitoring process.
logs_response = requests.post(
    f"{BASE_URL}/logs/save",
    json={
        "logData": {
            "processId": process_id,
            "productionLineId": "chemical-production-line-001",
            "parameters": {
                "temperature": 85,
                "pressure": 12,
                "materialTypes": ["plastic", "metal", "glass"],
            },
        }
    },
)
logs_response.raise_for_status()

# Add a recycling center with its location, capacity, and contact details.
center_response = requests.post(
    f"{BASE_URL}/recycling-centers",
    json={
        "name": "Central Materials Recovery Center",
        "location": "100 Greenway Road",
        "capacity": 500,
        "contact": {
            "name": "Jordan Lee",
            "phone": "+1-555-0100",
            "email": "jordan.lee@example.com",
        },
    },
)
center_response.raise_for_status()

