import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

transaction_payload = {
    "propertyId": input("Property ID: ").strip(),
    "details": input("Transaction details: ").strip(),
}
transaction_response = session.post(
    f"{BASE_URL}/transactions",
    json=transaction_payload,
)
transaction_response.raise_for_status()
transaction = transaction_response.json()
transaction_id = transaction["id"]

report_payload = {
    "criteria": {
        "region": input("Report region: ").strip(),
        "property_type": input("Report property type: ").strip(),
    },
    "preferences": {
        "analysis": input("Report analysis preferences: ").strip(),
    },
}
report_response = session.post(
    f"{BASE_URL}/custom-reports",
    json=report_payload,
)
report_response.raise_for_status()

tour_feedback = input("Feedback for the property tour: ").strip()
print(f"Tour feedback captured: {tour_feedback}")

finalize_response = session.post(
    f"{BASE_URL}/transactions/{transaction_id}/finalize",
)
finalize_response.raise_for_status()
print(finalize_response.json())
